import torch

def cubic_w(t, a=-0.75):
    t = abs(t)
    if t <= 1:
        return (a + 2) * t**3 - (a + 3) * t**2 + 1
    if t < 2:
        return a * t**3 - 5 * a * t**2 + 8 * a * t - 4 * a
    return 0.0

S = torch.zeros(64, 32)
for r in range(64):
    c = (r + 0.5) / 2 - 0.5
    base = int(torch.floor(torch.tensor(c)))
    for k in range(-1, 3):
        j = base + k
        if 0 <= j < 32:
            S[r, j] += cubic_w(c - j)

S_T = S.t().contiguous()

def forward(module, x):
    X = x.view(640, 32, 32)
    t1 = torch.bmm(X, S_T.expand(640, -1, -1))       # gemm (rows)
    t2 = t1.transpose(1, 2).contiguous()             # layout
    t3 = torch.bmm(t2, S_T.expand(640, -1, -1))      # gemm (cols)
    return t3.view(1, 640, 64, 64)                   # layout

