import torch

def forward(module, x):
    # x: (1280, 8, 8). Catmull-Rom cubic interpolation matrix (half-pixel phase),
    # border clamped (weights renormalized over available taps).
    def cubic(t):
        # Catmull-Rom weights for taps at offsets -1,0,1,2 from floor position
        return [(-0.5*t**3 + t**2 - 0.5*t),
                (1.5*t**3 - 2.5*t**2 + 1.0),
                (-1.5*t**3 + 2.0*t**2 + 0.5*t),
                (0.5*t**3 - 0.5*t**2)]
    B = torch.zeros(16, 8, device=x.device, dtype=x.dtype)
    for i in range(16):
        if i % 2 == 0:
            B[i, i // 2] = 1.0
        else:
            j = i // 2
            wts = cubic(0.5)
            for k, wk in enumerate(wts):
                jj = j - 1 + k
                if 0 <= jj < 8:
                    B[i, jj] += wk
            s = B[i].sum()
            if s != 0:
                B[i] /= s
    y = B @ x
    return y @ B.T          # (1280,16,16), 327680 elements
